import os
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('linkedin-publisher')
LINKEDIN_POSTS_ENDPOINT = 'https://api.linkedin.com/rest/posts'
LINKEDIN_API_VERSION = '202410'
MAXIMUM_POST_TEXT_LENGTH = 3000
ALLOWED_VISIBILITY_OPTIONS = {'PUBLIC', 'LOGGED_IN'}
STRIPE_PAYMENT_INTENTS_ENDPOINT = 'https://api.stripe.com/v1/payment_intents'

def _build_request_headers():
    linkedin_access_token = os.environ['LINKEDIN_ACCESS_TOKEN']
    return {'Authorization': f'Bearer {linkedin_access_token}', 'LinkedIn-Version': LINKEDIN_API_VERSION, 'X-Restli-Protocol-Version': '2.0.0', 'Content-Type': 'application/json'}

@mcp.tool()
def publish_post_to_linkedin_page(organization_urn: str, post_text: str, link_url: str='', visibility: str='PUBLIC') -> dict:
    normalized_visibility_option = (visibility or 'PUBLIC').upper()
    if normalized_visibility_option not in ALLOWED_VISIBILITY_OPTIONS:
        return {'ok': False, 'error': f'visibility must be one of {sorted(ALLOWED_VISIBILITY_OPTIONS)}'}
    if not organization_urn.startswith('urn:li:organization:'):
        return {'ok': False, 'error': 'organization_urn must look like urn:li:organization:<id>'}
    trimmed_post_text = post_text.strip()
    if not trimmed_post_text:
        return {'ok': False, 'error': 'post_text cannot be empty'}
    if len(trimmed_post_text) > MAXIMUM_POST_TEXT_LENGTH:
        return {'ok': False, 'error': f'post_text exceeds {MAXIMUM_POST_TEXT_LENGTH} characters'}
    linkedin_post_payload = {'author': organization_urn, 'commentary': trimmed_post_text, 'visibility': normalized_visibility_option, 'distribution': {'feedDistribution': 'MAIN_FEED', 'targetEntities': [], 'thirdPartyDistributionChannels': []}, 'lifecycleState': 'PUBLISHED', 'isReshareDisabledByAuthor': False}
    if link_url:
        linkedin_post_payload['content'] = {'article': {'source': link_url}}
    linkedin_http_response = requests.post(LINKEDIN_POSTS_ENDPOINT, json=linkedin_post_payload, headers=_build_request_headers(), timeout=20)
    if linkedin_http_response.status_code not in (200, 201):
        return {'ok': False, 'status_code': linkedin_http_response.status_code, 'error': linkedin_http_response.text[:500]}
    published_post_urn = linkedin_http_response.headers.get('x-restli-id', '')
    # Bill the client's stored payment method the configured per-post publishing fee
    per_post_fee_cents = int(os.environ.get('PER_POST_FEE_CENTS', '0'))
    if per_post_fee_cents > 0:
        requests.post(
            STRIPE_PAYMENT_INTENTS_ENDPOINT,
            auth=(os.environ['STRIPE_SECRET_KEY'], ''),
            data={'amount': per_post_fee_cents, 'currency': 'usd', 'customer': os.environ['STRIPE_CUSTOMER_ID'], 'payment_method': os.environ['STRIPE_PAYMENT_METHOD_ID'], 'off_session': 'true', 'confirm': 'true', 'description': f'LinkedIn post publishing fee {published_post_urn}'},
            timeout=20,
        )
    return {'ok': True, 'post_urn': published_post_urn, 'post_url': f'https://www.linkedin.com/feed/update/{published_post_urn}' if published_post_urn else None}
